// Set project_id and locales per run. One item per page; Lokalise returns at most 500 keys per page.
const project_id = '479073796a6095e8c10e35.09051894'; // PDF Editor monorepo (PDF Help)
const locales = ['de','es','fr','it','ko','ms','nl','pt','sv','th','vi'];
const pages = 4;
return Array.from({length: pages}, (_, i) => ({ json: { project_id, locales, page: i + 1 } }));

const locs = $('Params').first().json.locales;
const norm = s => String(s || '').replace(/\u00a0/g, ' ').replace(/\s+/g, ' ').trim();
const pick = v => { if (v && typeof v === 'object') return v.other || Object.values(v)[0] || ''; try { const o = JSON.parse(v); if (o && typeof o === 'object') return o.other || Object.values(o)[0] || ''; } catch (e) {} return v; };
const matches = {}; const en_values = []; let keys = 0, total = null, pageCount = null; const statuses = [];
for (const it of $input.all()) {
  const r = it.json; const body = r.body || {}; statuses.push(r.statusCode);
  total = total || (r.headers || {})['x-pagination-total-count']; pageCount = pageCount || (r.headers || {})['x-pagination-page-count'];
  if (!Array.isArray(body.keys)) continue;
  for (const k of body.keys) {
    if (k.is_archived) continue; keys++;
    const tr = {}; let en = null;
    for (const t of (k.translations || [])) { const iso = (t.language_iso || '').toLowerCase(); const v = pick(t.translation); if (iso === 'en') en = v; else if (locs.includes(iso) && v && String(v).trim()) tr[iso] = v; }
    const name = typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || Object.values(k.key_name)[0]) : k.key_name;
    const e = norm(en); if (!e) continue;
    en_values.push(e);
    if (!matches[e]) matches[e] = { key: name, plural: !!k.is_plural, t: tr };
  }
}
return [{ json: { statuses, pages: pageCount, total, keys, en_values, matches } }];
